let fluid;
let t = 0;

function setup() {
  // WEBGL mode is required for 3D
  createCanvas(600, 600, WEBGL); 

  // High frame rate not guaranteed in JS CPU simulation, but we try
  frameRate(60); 

  // dt, diffusion, viscosity
  fluid = new Fluid(0.1, 0, 0.000001);

  // Initialize color mode for nice visuals
  colorMode(HSB, 255);
}

function draw() {
  background(0);

  // Orbital controls allow mouse to rotate the camera around the fluid
  orbitControl();

  // Add density and velocity at the center of the cube
  let cx = int(0.5 * N);
  let cy = int(0.5 * N);
  let cz = int(0.5 * N);

  // Inject Noise-based movement
  for (let i = -1; i <= 1; i++) {
    for (let j = -1; j <= 1; j++) {
      for (let k = -1; k <= 1; k++) {
        // Add "Dye"
        fluid.addDensity(cx + i, cy + j, cz + k, random(50, 150));

        // Circular/Swirling Velocity pattern using Noise
        let angleX = noise(t) * TWO_PI * 2;
        let angleY = noise(t + 100) * TWO_PI * 2;
        let angleZ = noise(t + 200) * TWO_PI * 2;

        let v = p5.Vector.fromAngles(angleX, angleY);
        v.mult(2); // Speed

        fluid.addVelocity(cx + i, cy + j, cz + k, v.x, v.y, v.z);
      }
    }
  }

  t += 0.01;

  fluid.step();
  fluid.renderD();
  fluid.fadeD();
}

