import { GoogleGenAI } from "@google/genai";
import { FluidConfig } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateFluidExplanation = async (
  query: string, 
  currentConfig: FluidConfig
): Promise<string> => {
  try {
    const configContext = `
      Current Simulation Parameters:
      - Diffusion: ${currentConfig.diffusion}
      - Viscosity: ${currentConfig.viscosity}
      - Time Step (dt): ${currentConfig.dt}
      - Solver Iterations: ${currentConfig.solverIterations}
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `
        You are an expert Physics and Computer Science assistant embedded in a 3D Fluid Dynamics Simulation.
        The simulation uses a grid-based stable fluids solver (Jos Stam's method extended to 3D).

        ${configContext}

        User Question: ${query}

        Provide a concise, educational, and scientifically accurate answer. 
        If the user asks about the parameters, explain how changing them affects the visual simulation.
        Keep the tone technical but accessible.
      `,
    });

    return response.text || "I couldn't generate an explanation at this moment.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "An error occurred while communicating with the AI. Please check your API key.";
  }
};

// 3D Fluid Solver based on Jos Stam's Real-Time Fluid Dynamics for Games
// Adapted for JavaScript/TypeScript

export class Fluid {
    size: number;
    dt: number;
    diff: number;
    visc: number;

    s: number[];
    density: number[];

    Vx: number[];
    Vy: number[];
    Vz: number[];

    Vx0: number[];
    Vy0: number[];
    Vz0: number[];

    iter: number; // Solver iterations

    constructor(dt: number, diffusion: number, viscosity: number, size: number) {
      this.size = size;
      this.dt = dt;
      this.diff = diffusion;
      this.visc = viscosity;
      this.iter = 4; // Low iteration count for real-time JS performance

      const N = this.size;
      const count = N * N * N;

      this.s = new Array(count).fill(0);
      this.density = new Array(count).fill(0);

      this.Vx = new Array(count).fill(0);
      this.Vy = new Array(count).fill(0);
      this.Vz = new Array(count).fill(0);

      this.Vx0 = new Array(count).fill(0);
      this.Vy0 = new Array(count).fill(0);
      this.Vz0 = new Array(count).fill(0);
    }

    updateConfig(dt: number, diff: number, visc: number) {
      this.dt = dt;
      this.diff = diff;
      this.visc = visc;
    }

    step() {
      const N = this.size;
      const dt = this.dt;
      const diff = this.diff;
      const visc = this.visc;

      this.diffuse(1, this.Vx0, this.Vx, visc, dt);
      this.diffuse(2, this.Vy0, this.Vy, visc, dt);
      this.diffuse(3, this.Vz0, this.Vz, visc, dt);

      this.project(this.Vx0, this.Vy0, this.Vz0, this.Vx, this.Vy);

      this.advect(1, this.Vx, this.Vx0, this.Vx0, this.Vy0, this.Vz0, dt);
      this.advect(2, this.Vy, this.Vy0, this.Vx0, this.Vy0, this.Vz0, dt);
      this.advect(3, this.Vz, this.Vz0, this.Vx0, this.Vy0, this.Vz0, dt);

      this.project(this.Vx, this.Vy, this.Vz, this.Vx0, this.Vy0);

      this.diffuse(0, this.s, this.density, diff, dt);
      this.advect(0, this.density, this.s, this.Vx, this.Vy, this.Vz, dt);
    }

    addDensity(x: number, y: number, z: number, amount: number) {
      const index = this.IX(x, y, z);
      this.density[index] += amount;
      // Clamp for visual sanity
      if (this.density[index] > 255) this.density[index] = 255;
    }

    addVelocity(x: number, y: number, z: number, amountX: number, amountY: number, amountZ: number) {
      const index = this.IX(x, y, z);
      this.Vx[index] += amountX;
      this.Vy[index] += amountY;
      this.Vz[index] += amountZ;
    }

    // Fade density over time to prevent saturation
    fadeD() {
      for (let i = 0; i < this.density.length; i++) {
        this.density[i] *= 0.96; // Fade factor
      }
    }

    // --- Solvers ---

    IX(x: number, y: number, z: number) {
      // Clamp coordinates
      if (x < 0) x = 0; if (x >= this.size) x = this.size - 1;
      if (y < 0) y = 0; if (y >= this.size) y = this.size - 1;
      if (z < 0) z = 0; if (z >= this.size) z = this.size - 1;
      return x + y * this.size + z * this.size * this.size;
    }

    lin_solve(b: number, x: number[], x0: number[], a: number, c: number) {
      const cRecip = 1.0 / c;
      const N = this.size;

      for (let k = 0; k < this.iter; k++) {
        for (let m = 1; m < N - 1; m++) {
          for (let j = 1; j < N - 1; j++) {
            for (let i = 1; i < N - 1; i++) {
                x[this.IX(i, j, m)] =
                    (x0[this.IX(i, j, m)] +
                        a * (
                            x[this.IX(i + 1, j, m)] +
                            x[this.IX(i - 1, j, m)] +
                            x[this.IX(i, j + 1, m)] +
                            x[this.IX(i, j - 1, m)] +
                            x[this.IX(i, j, m + 1)] +
                            x[this.IX(i, j, m - 1)]
                        )) * cRecip;
            }
          }
        }
        this.set_bnd(b, x);
      }
    }

    diffuse(b: number, x: number[], x0: number[], diff: number, dt: number) {
      const N = this.size;
      const a = dt * diff * (N - 2) * (N - 2);
      this.lin_solve(b, x, x0, a, 1 + 6 * a);
    }

    project(velocX: number[], velocY: number[], velocZ: number[], p: number[], div: number[]) {
        const N = this.size;
        for (let k = 1; k < N - 1; k++) {
            for (let j = 1; j < N - 1; j++) {
                for (let i = 1; i < N - 1; i++) {
                    div[this.IX(i, j, k)] = -0.5 * (
                         velocX[this.IX(i + 1, j, k)] - velocX[this.IX(i - 1, j, k)] +
                         velocY[this.IX(i, j + 1, k)] - velocY[this.IX(i, j - 1, k)] +
                         velocZ[this.IX(i, j, k + 1)] - velocZ[this.IX(i, j, k - 1)]
                    ) / N;
                    p[this.IX(i, j, k)] = 0;
                }
            }
        }
        this.set_bnd(0, div);
        this.set_bnd(0, p);
        this.lin_solve(0, p, div, 1, 6);

        for (let k = 1; k < N - 1; k++) {
            for (let j = 1; j < N - 1; j++) {
                for (let i = 1; i < N - 1; i++) {
                    velocX[this.IX(i, j, k)] -= 0.5 * N * (p[this.IX(i + 1, j, k)] - p[this.IX(i - 1, j, k)]);
                    velocY[this.IX(i, j, k)] -= 0.5 * N * (p[this.IX(i, j + 1, k)] - p[this.IX(i, j - 1, k)]);
                    velocZ[this.IX(i, j, k)] -= 0.5 * N * (p[this.IX(i, j, k + 1)] - p[this.IX(i, j, k - 1)]);
                }
            }
        }
        this.set_bnd(1, velocX);
        this.set_bnd(2, velocY);
        this.set_bnd(3, velocZ);
    }

    advect(b: number, d: number[], d0: number[], velocX: number[], velocY: number[], velocZ: number[], dt: number) {
      const N = this.size;
      let i0, i1, j0, j1, k0, k1;

      const dtx = dt * (N - 2);
      const dty = dt * (N - 2);
      const dtz = dt * (N - 2);

      let s0, s1, t0, t1, u0, u1;
      let tmp1, tmp2, tmp3, x, y, z;

      const Nfloat = N;
      let ifloat, jfloat, kfloat;
      let i, j, k;

      for(k = 1, kfloat = 1; k < N - 1; k++, kfloat++) {
          for(j = 1, jfloat = 1; j < N - 1; j++, jfloat++) {
              for(i = 1, ifloat = 1; i < N - 1; i++, ifloat++) {
                  tmp1 = dtx * velocX[this.IX(i, j, k)];
                  tmp2 = dty * velocY[this.IX(i, j, k)];
                  tmp3 = dtz * velocZ[this.IX(i, j, k)];

                  x = ifloat - tmp1;
                  y = jfloat - tmp2;
                  z = kfloat - tmp3;

                  if(x < 0.5) x = 0.5;
                  if(x > Nfloat + 0.5) x = Nfloat + 0.5;
                  i0 = Math.floor(x);
                  i1 = i0 + 1.0;

                  if(y < 0.5) y = 0.5;
                  if(y > Nfloat + 0.5) y = Nfloat + 0.5;
                  j0 = Math.floor(y);
                  j1 = j0 + 1.0;

                  if(z < 0.5) z = 0.5;
                  if(z > Nfloat + 0.5) z = Nfloat + 0.5;
                  k0 = Math.floor(z);
                  k1 = k0 + 1.0;

                  s1 = x - i0;
                  s0 = 1.0 - s1;
                  t1 = y - j0;
                  t0 = 1.0 - t1;
                  u1 = z - k0;
                  u0 = 1.0 - u1;

                  const i0i = Math.floor(i0);
                  const i1i = Math.floor(i1);
                  const j0i = Math.floor(j0);
                  const j1i = Math.floor(j1);
                  const k0i = Math.floor(k0);
                  const k1i = Math.floor(k1);

                  d[this.IX(i, j, k)] =
                      s0 * (t0 * (u0 * d0[this.IX(i0i, j0i, k0i)] + u1 * d0[this.IX(i0i, j0i, k1i)]) +
                            t1 * (u0 * d0[this.IX(i0i, j1i, k0i)] + u1 * d0[this.IX(i0i, j1i, k1i)])) +
                      s1 * (t0 * (u0 * d0[this.IX(i1i, j0i, k0i)] + u1 * d0[this.IX(i1i, j0i, k1i)]) +
                            t1 * (u0 * d0[this.IX(i1i, j1i, k0i)] + u1 * d0[this.IX(i1i, j1i, k1i)]));
              }
          }
      }
      this.set_bnd(b, d);
    }

    set_bnd(b: number, x: number[]) {
      const N = this.size;
      for(let j = 1; j < N - 1; j++) {
          for(let i = 1; i < N - 1; i++) {
              x[this.IX(i, j, 0)] = b === 3 ? -x[this.IX(i, j, 1)] : x[this.IX(i, j, 1)];
              x[this.IX(i, j, N - 1)] = b === 3 ? -x[this.IX(i, j, N - 2)] : x[this.IX(i, j, N - 2)];
          }
      }
      for(let k = 1; k < N - 1; k++) {
          for(let i = 1; i < N - 1; i++) {
              x[this.IX(i, 0, k)] = b === 2 ? -x[this.IX(i, 1, k)] : x[this.IX(i, 1, k)];
              x[this.IX(i, N - 1, k)] = b === 2 ? -x[this.IX(i, N - 2, k)] : x[this.IX(i, N - 2, k)];
          }
      }
      for(let k = 1; k < N - 1; k++) {
          for(let j = 1; j < N - 1; j++) {
              x[this.IX(0, j, k)] = b === 1 ? -x[this.IX(1, j, k)] : x[this.IX(1, j, k)];
              x[this.IX(N - 1, j, k)] = b === 1 ? -x[this.IX(N - 2, j, k)] : x[this.IX(N - 2, j, k)];
          }
      }

      x[this.IX(0, 0, 0)] = 0.33 * (x[this.IX(1, 0, 0)] + x[this.IX(0, 1, 0)] + x[this.IX(0, 0, 1)]);
      x[this.IX(0, N - 1, 0)] = 0.33 * (x[this.IX(1, N - 1, 0)] + x[this.IX(0, N - 2, 0)] + x[this.IX(0, N - 1, 1)]);
      x[this.IX(0, 0, N - 1)] = 0.33 * (x[this.IX(1, 0, N - 1)] + x[this.IX(0, 1, N - 1)] + x[this.IX(0, 0, N - 2)]);
      x[this.IX(0, N - 1, N - 1)] = 0.33 * (x[this.IX(1, N - 1, N - 1)] + x[this.IX(0, N - 2, N - 1)] + x[this.IX(0, N - 1, N - 2)]);
      x[this.IX(N - 1, 0, 0)] = 0.33 * (x[this.IX(N - 2, 0, 0)] + x[this.IX(N - 1, 1, 0)] + x[this.IX(N - 1, 0, 1)]);
      x[this.IX(N - 1, N - 1, 0)] = 0.33 * (x[this.IX(N - 2, N - 1, 0)] + x[this.IX(N - 1, N - 2, 0)] + x[this.IX(N - 1, N - 1, 1)]);
      x[this.IX(N - 1, 0, N - 1)] = 0.33 * (x[this.IX(N - 2, 0, N - 1)] + x[this.IX(N - 1, 1, N - 1)] + x[this.IX(N - 1, 0, N - 2)]);
      x[this.IX(N - 1, N - 1, N - 1)] = 0.33 * (x[this.IX(N - 2, N - 1, N - 1)] + x[this.IX(N - 1, N - 2, N - 1)] + x[this.IX(N - 1, N - 1, N - 2)]);
    }
}

import React, { useEffect, useRef } from 'react';
import p5 from 'p5';
import { Fluid } from '../utils/fluidSolver';
import { FluidConfig } from '../types';

interface FluidCanvasProps {
  config: FluidConfig;
  onFpsUpdate: (fps: number) => void;
}

const FluidCanvas: React.FC<FluidCanvasProps> = ({ config, onFpsUpdate }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const p5InstanceRef = useRef<p5 | null>(null);
  const fluidRef = useRef<Fluid | null>(null);

  // Sync config with ref to avoid re-initializing sketch on prop change
  const configRef = useRef(config);
  useEffect(() => {
    configRef.current = config;
    if (fluidRef.current) {
        fluidRef.current.updateConfig(config.dt, config.diffusion, config.viscosity);
    }
  }, [config]);

  useEffect(() => {
    if (!containerRef.current) return;

    const sketch = (p: p5) => {
      let fluid: Fluid;
      let t = 0;
      const N = 32; // Grid Size
      const SCALE = 6; // Visual scaling

      p.setup = () => {
        // WEBGL mode is required for 3D
        p.createCanvas(p.windowWidth, p.windowHeight, p.WEBGL);

        // Use props config for initialization
        fluid = new Fluid(configRef.current.dt, configRef.current.diffusion, configRef.current.viscosity, N);
        fluidRef.current = fluid;

        p.colorMode(p.HSB, 255);
        p.noStroke();
      };

      p.windowResized = () => {
        p.resizeCanvas(p.windowWidth, p.windowHeight);
      };

      p.draw = () => {
        p.background(0);

        // Orbital controls allow mouse to rotate the camera around the fluid
        p.orbitControl();

        // Add density and velocity at the center of the cube
        const cx = Math.floor(0.5 * N);
        const cy = Math.floor(0.5 * N);
        const cz = Math.floor(0.5 * N);

        // Inject Noise-based movement
        for (let i = -1; i <= 1; i++) {
          for (let j = -1; j <= 1; j++) {
            for (let k = -1; k <= 1; k++) {
              // Add "Dye"
              fluid.addDensity(cx + i, cy + j, cz + k, p.random(50, 150));

              // Circular/Swirling Velocity pattern using Noise
              const angleX = p.noise(t) * p.TWO_PI * 2;
              const angleY = p.noise(t + 100) * p.TWO_PI * 2;

              const v = p5.Vector.fromAngles(angleX, angleY);
              v.mult(2); // Speed

              // We project the 2D noise vector into 3D for simplicity, or add another noise channel
              const angleZ = p.noise(t + 200) * p.TWO_PI;
              const vz = Math.sin(angleZ) * 2;

              fluid.addVelocity(cx + i, cy + j, cz + k, v.x, v.y, vz);
            }
          }
        }

        t += 0.01;

        fluid.step();

        // Custom Render Logic (Points)
        p.push();
        // Center the grid
        p.translate(-N * SCALE / 2, -N * SCALE / 2, -N * SCALE / 2);

        // Render Density
        p.strokeWeight(SCALE * 1.5); 

        for (let k = 0; k < N; k++) {
            for (let j = 0; j < N; j++) {
                for (let i = 0; i < N; i++) {
                    const idx = fluid.IX(i, j, k);
                    const d = fluid.density[idx];

                    if (d > 5) { // Only render visible density
                        // Color based on position/density for style
                        const hue = (d + t * 20) % 255; 
                        p.stroke(hue, 200, d);
                        p.point(i * SCALE, j * SCALE, k * SCALE);
                    }
                }
            }
        }
        p.pop();

        fluid.fadeD();

        if (p.frameCount % 30 === 0) {
            onFpsUpdate(Math.floor(p.frameRate()));
        }
      };
    };

    // Cleanup previous instance
    if (p5InstanceRef.current) {
        p5InstanceRef.current.remove();
    }

    p5InstanceRef.current = new p5(sketch, containerRef.current);

    return () => {
      if (p5InstanceRef.current) {
        p5InstanceRef.current.remove();
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []); // Run once on mount, updates handled via refs

  return <div ref={containerRef} className="absolute inset-0 z-0" />;
};

export default FluidCanvas;

import React from 'react';
import { FluidConfig } from '../types';

interface ControlPanelProps {
  config: FluidConfig;
  setConfig: React.Dispatch<React.SetStateAction<FluidConfig>>;
  fps: number;
}

const ControlPanel: React.FC<ControlPanelProps> = ({ config, setConfig, fps }) => {
  const handleChange = (key: keyof FluidConfig, value: number) => {
    setConfig(prev => ({ ...prev, [key]: value }));
  };

  return (
    <div className="absolute top-4 left-4 z-10 w-64 bg-black/60 backdrop-blur-md border border-white/10 rounded-xl p-4 text-white shadow-xl">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-lg font-bold bg-gradient-to-r from-cyan-400 to-purple-500 bg-clip-text text-transparent">
          NebulaFlow 3D
        </h2>
        <span className="text-xs font-mono text-green-400">{fps} FPS</span>
      </div>

      <div className="space-y-4">
        <div>
          <label className="flex justify-between text-xs text-gray-400 mb-1">
            <span>Viscosity</span>
            <span>{config.viscosity.toFixed(7)}</span>
          </label>
          <input
            type="range"
            min="0"
            max="0.0001"
            step="0.0000001"
            value={config.viscosity}
            onChange={(e) => handleChange('viscosity', parseFloat(e.target.value))}
            className="w-full h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-cyan-500"
          />
        </div>

        <div>
          <label className="flex justify-between text-xs text-gray-400 mb-1">
            <span>Diffusion</span>
            <span>{config.diffusion.toFixed(7)}</span>
          </label>
          <input
            type="range"
            min="0"
            max="0.0001"
            step="0.0000001"
            value={config.diffusion}
            onChange={(e) => handleChange('diffusion', parseFloat(e.target.value))}
            className="w-full h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-purple-500"
          />
        </div>

        <div>
          <label className="flex justify-between text-xs text-gray-400 mb-1">
            <span>Time Step (dt)</span>
            <span>{config.dt.toFixed(2)}</span>
          </label>
          <input
            type="range"
            min="0.01"
            max="0.5"
            step="0.01"
            value={config.dt}
            onChange={(e) => handleChange('dt', parseFloat(e.target.value))}
            className="w-full h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
          />
        </div>
      </div>

      <div className="mt-4 pt-4 border-t border-white/10 text-[10px] text-gray-500">
        <p>Left Click: Rotate</p>
        <p>Scroll: Zoom</p>
      </div>
    </div>
  );
};

export default ControlPanel;

import React, { useState, useRef, useEffect } from 'react';
import { generateFluidExplanation } from '../services/geminiService';
import { ChatMessage, FluidConfig } from '../types';

interface ChatInterfaceProps {
  config: FluidConfig;
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({ config }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'Hi! I am the simulation AI. Ask me about fluid dynamics or the current parameters.', timestamp: Date.now() }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: ChatMessage = { role: 'user', text: input, timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    const responseText = await generateFluidExplanation(userMsg.text, config);

    setMessages(prev => [...prev, { role: 'model', text: responseText, timestamp: Date.now() }]);
    setIsLoading(false);
  };

  if (!isOpen) {
    return (
      <button
        onClick={() => setIsOpen(true)}
        className="absolute bottom-6 right-6 z-20 w-14 h-14 bg-gradient-to-br from-cyan-500 to-blue-600 rounded-full shadow-lg flex items-center justify-center text-white hover:scale-110 transition-transform duration-200 group"
      >
        <i className="fas fa-sparkles text-xl group-hover:rotate-12 transition-transform"></i>
      </button>
    );
  }

  return (
    <div className="absolute bottom-6 right-6 z-20 w-80 sm:w-96 h-[500px] bg-black/80 backdrop-blur-xl border border-white/10 rounded-2xl shadow-2xl flex flex-col overflow-hidden animate-in fade-in slide-in-from-bottom-10 duration-300">
      {/* Header */}
      <div className="p-4 border-b border-white/10 flex justify-between items-center bg-white/5">
        <div className="flex items-center gap-2">
           <i className="fas fa-robot text-cyan-400"></i>
           <h3 className="font-semibold text-sm">Gemini Science Guide</h3>
        </div>
        <button 
          onClick={() => setIsOpen(false)}
          className="text-gray-400 hover:text-white transition-colors"
        >
          <i className="fas fa-times"></i>
        </button>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4 scrollbar-hide">
        {messages.map((msg, idx) => (
          <div
            key={idx}
            className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div
              className={`max-w-[85%] p-3 rounded-2xl text-sm leading-relaxed ${
                msg.role === 'user'
                  ? 'bg-blue-600 text-white rounded-br-none'
                  : 'bg-white/10 text-gray-100 rounded-bl-none'
              }`}
            >
              {msg.text}
            </div>
          </div>
        ))}
        {isLoading && (
            <div className="flex justify-start">
                <div className="bg-white/10 p-3 rounded-2xl rounded-bl-none flex gap-1 items-center">
                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></div>
                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce delay-100"></div>
                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce delay-200"></div>
                </div>
            </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input */}
      <div className="p-4 border-t border-white/10 bg-black/20">
        <div className="flex gap-2">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Ask about viscosity..."
            className="flex-1 bg-white/5 border border-white/10 rounded-xl px-4 py-2 text-sm focus:outline-none focus:border-cyan-500/50 transition-colors"
          />
          <button
            onClick={handleSend}
            disabled={isLoading}
            className="bg-cyan-600 hover:bg-cyan-500 text-white p-2 rounded-xl transition-colors disabled:opacity-50 w-10 flex items-center justify-center"
          >
            <i className="fas fa-paper-plane text-xs"></i>
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatInterface;

